export type GameAssetModuleEffectRow = {
  type: number
  rarity: number
  benefit: number
  benefitType: number
  clusterIndex: number
}

export const MODULE_EFFECTS_TABLE: Readonly<Record<string, GameAssetModuleEffectRow>> =
  (TOWER_ASSET_TABLES.moduleEffects?.effects ?? {}) as Readonly<Record<string, GameAssetModuleEffectRow>>

type GameAssetTablesShape = typeof TOWER_ASSET_TABLES & {
  labResearch?: unknown
  cards?: unknown
  techTree?: unknown
  guardians?: unknown
}

export const LAB_RESEARCH_ASSET_TABLE = (TOWER_ASSET_TABLES as GameAssetTablesShape).labResearch ?? null
export const CARDS_ASSET_TABLE = (TOWER_ASSET_TABLES as GameAssetTablesShape).cards ?? null
export const TECH_TREE_ASSET_TABLE = (TOWER_ASSET_TABLES as GameAssetTablesShape).techTree ?? null
export const GUARDIANS_ASSET_TABLE = (TOWER_ASSET_TABLES as GameAssetTablesShape).guardians ?? null

export function isModuleEffectsTablePopulated(): boolean {
  return Object.values(MODULE_EFFECTS_TABLE).some(
    row => row.clusterIndex > 0 || row.rarity > 0 || row.benefit > 0,
  )
}
